tz_def('CONFUSION_DESC', '每種神器都會使山洞容量增加一定數量。在此神器力量範圍內的村莊，投石機只能隨機射擊。世界奇蹟始終可以被指定為目標，寶物庫也始終可以被指定為目標，但獨特神器除外。瞄準資源田時只能隨機命中資源田，瞄準建築時只能隨機命中建築。');
