tz_def('WWVILLAGE', '世界奇蹟村莊');
tz_def('ARTEFACT', '<h1><b>納塔神器</b></h1>

村莊裡低語著種種傳聞，傳頌只有最出色的說書人才會講的傳說。說的是納塔，Travian 世界中最令人畏懼的戰士。擊殺他們是每位英雄的夢想，也是每位戰士的目標。沒有人知道納塔何以獲得如此強大的力量，他們的戰士又為何如此殘忍。戰士們決心找出納塔力量的來源，派出一隊精銳探子前去偵察。沒過多久，探子便帶著恐懼的眼神回來，並提出不可思議的推測：那股力量似乎來自他們稱為神器的神秘物品，而那些神器是從我們祖先手中偷走的。試著奪取他們的神器，你就能駕馭那股力量。

<img src="/img/x.gif" class="ArtefactsAnnouncement">

奪取神器的時刻到了。與你的聯盟合作，帶領戰士去取得這些眾人覬覦的物品。然而，納塔不會不戰而放棄神器……你的敵人也一樣。若你成功取回神器並擊退敵人，便能收下獎勵。你的建築會變得無比堅固強大，部隊也會更快，並消耗更少糧食。奪下神器，為你的帝國帶來榮耀，成為追隨者口中的新傳說。

要偷取一件神器，必須達成以下條件：

1. 你必須攻擊該村莊（不可掠奪！）
2. 攻擊必須獲勝
3. 摧毀寶物庫
4. 發動該次攻擊的村莊必須有一座空的寶物庫：小型神器需等級 10，大型神器需等級 20
5. 攻擊中必須有英雄

若未達成，下一次帶著英雄、並有空寶物庫且獲勝的攻擊，便會取走神器。

要建造世界奇蹟，你本人（也就是世界奇蹟村莊的擁有者）必須持有一份建築圖紙，才能從等級 0 建到 50；從 51 到 100，你的聯盟還需要額外一份建築圖紙！同一世界奇蹟村莊帳號持有兩份圖紙並不會生效！

建築圖紙一在伺服器上出現即可征服。

遊戲中會有倒數計時，在開放前 5 天顯示確切的釋出時間。');

//WW Village Release Message
tz_def('WWVILLAGEMSG', '<h1><b>世界奇蹟村莊</b></h1>

自從第一次在可怖納塔那些被詛咒的村莊城牆上交戰以來，無數日子已經過去。自由之民與納塔帝國的許多軍隊，都在納塔昔日統治世間的諸多要塞前奮戰並死去。如今塵埃落定，一時的平靜到來，各軍開始清點損失、收殮死者。夜空裡仍飄著戰鬥的氣味，那是一場規模與殘暴都難以忘懷的屠殺，卻很快就會被接下來的戰役比下去。自由之民與可怖納塔最龐大的軍隊，正再度集結，準備對納塔帝國昔日令人覬覦的要塞發動新的突擊。
不久，偵察兵帶回了既壯麗又令人膽寒的消息：一支規模難以想像的可怖大軍，正在世界盡頭、納塔的首都集結。那支軍隊如此龐大、勢不可擋，行軍揚起的塵土足以遮蔽所有光線；又如此殘暴無情，足以粉碎一切希望。自由之民知道，他們現在必須與時間賽跑，也必須與納塔帝國無盡的大軍賽跑，建起一座世界奇蹟，讓世界恢復和平，並消滅納塔的威脅。
然而，建起如此偉大的奇蹟絕非易事。你需要遠古時代留下的建築圖紙，那些圖紙如此奧秘，即便最睿智的賢者也不知其內容與下落。
數以萬計的偵察兵走遍世間，徒然尋找這些神秘圖紙。他們找遍各處，卻不敢踏入可怕的納塔首都，始終一無所獲。然而今天，他們帶回了好消息，也帶回了圖紙的所在：納塔軍隊把它們藏在秘密要塞裡，好讓凡人的眼睛看不見。
最後的旅程現在開始。自由之民與納塔最精銳的軍隊，將為蒼生的命運在全世界交鋒。這是一場會迴盪千古的戰爭，這是你的戰爭。你將在這裡把名字刻進歷史，你將在這裡成為傳說。

<img src="/img/x.gif" class="WWVillagesAnnouncement" title="'.WWVILLAGE.'" alt="'.WWVILLAGE.'">

要征服一座村莊，必須達成以下條件：

1. 你必須攻擊該村莊（不可掠奪！）
2. 攻擊必須獲勝
3. 摧毀行宮
4. 你必須用參議員、司令官、族長將忠誠度降到 0
5. 你必須有足夠的文化點才能征服該村莊

若未達成，下一次帶著參議員、司令官或族長獲勝，且行宮／皇宮仍有空位的攻擊，便會奪下該村莊。

要建造世界奇蹟，你本人（也就是世界奇蹟村莊的擁有者）必須持有一份建築圖紙，才能從等級 0 建到 50；從 51 到 100，你的聯盟還需要額外一份建築圖紙！同一世界奇蹟村莊帳號持有兩份圖紙並不會生效！

建築圖紙一在伺服器上出現即可征服。

遊戲中會有倒數計時，在開放前 '.(5 / SPEED).' 天顯示確切的釋出時間。');

//Building Plans
tz_def('WILL_SPAWN_IN', '將出現於');
tz_def('PLAN', '遠古建築圖紙');
tz_def('PLANVILLAGE', '世界奇蹟建築圖紙');
tz_def('PLAN_DESC', '有了這份遠古建築圖紙，你可以將世界奇蹟建造到等級 50。若要繼續建造，你的聯盟必須至少持有兩份圖紙。');
tz_def('PLAN_INFO', '<h1><b>世界奇蹟建築圖紙</b></h1>


許久以前，Travian 的各個種族對納塔出乎意料的回歸大吃一驚。這個自古以來在智慧、力量與榮耀上都超越眾人的種族，又要來困擾自由之民了。於是他們傾盡全力，準備與納塔打最後一戰，並永遠消滅他們。許多人認為，所謂的「世界奇蹟」——一座充滿傳說的建築——是唯一的辦法。傳說一旦建成，便能讓任何人立於不敗，最終使建造者成為已知 Travian 世界的統治者與征服者。

據說，要建造這樣的建築，必須先取得建築圖紙。因此建築師們想出巧妙的辦法，要把圖紙安全地存放起來。不久之後，許多城市與大都會裡便出現了神殿般的建築——寶物庫。

可悲的是，沒有人，即便博學多聞的智者，也不知道該去哪裡找這些建築圖紙。人們越是努力尋找，它們就越像只是傳說。

然而今天，這最後的秘密將被揭開。過去的匱乏與努力不會白費，因為今天數個種族的偵察兵已經成功得知建築圖紙的下落。它們被納塔嚴密看守，藏在散布於整個 Travian 的數座綠洲裡。只有最英勇的英雄才能奪得這樣一份圖紙，並安全帶回家，讓建造得以開始。

最終，我們將看到 Travian 的自由種族能否再次智取納塔，並一次消滅他們。不過，可別傻到以為納塔會不戰而退！

<img src="/img/x.gif" class="WWBuildingPlansAnnouncement" title="'.PLAN.'" alt="'.PLAN.'">

要從納塔手中偷取一套建築圖紙，必須達成以下條件：
- 你必須攻擊該村莊（不可掠奪！）
- 你必須贏得這場攻擊
- 你必須摧毀寶物庫
- 你的英雄必須參加該次攻擊，因為只有他能攜帶建築圖紙
- 發動該次攻擊的村莊必須有一座空的等級 10 寶物庫
注意：若該次攻擊未符合以上條件，下一次符合條件的攻擊便會取走建築圖紙。



要建造寶物庫，你需要等級 10 的主建築，而且該村莊不得建有世界奇蹟。

要建造世界奇蹟，你本人（也就是世界奇蹟村莊的擁有者）必須自行持有建築圖紙，才能從等級 0 建到 50；接著從等級 51 到 100，你的聯盟還需要額外一套建築圖紙！同一世界奇蹟村莊帳號持有兩套建築圖紙並不會生效！');

