tz_def('MANUAL_UDESC_87', '衝車是重型攻城兵器，用來撞擊敵方城牆。請好好保護它：它很慢，單獨時也毫無防備。');
tz_def('MANUAL_UDESC_88', '投石機把石塊投向遠方，摧毀敵方的建築與田地。必須由其他部隊好好保護。');
tz_def('MANUAL_UDESC_89', '雅爾迫使敵村順從自己的意志，降低忠誠度，直到對方宣誓效忠北方。');
tz_def('MANUAL_UDESC_90', '拓荒者是勇敢的臣民，會出發為維京人建立新村莊。需要三人同行，並帶上物資。');
tz_def('HEALING_TIME_LEVEL', '治療時間於等級');
tz_def('BARRICADE_DESC', '拒馬保護你的村莊，抵禦其他玩家的攻擊。層層木造結構提供穩固的防禦加成。<br>僅限維京人');
