tz_def('MANUAL_DESC_TRAPPER', '陷阱機用隱藏良好的陷阱保護你的村莊。這表示大意的敵人會被囚禁，再也無法傷害你的村莊。');
tz_def('MANUAL_ONE_TRAP_COSTS', '一個陷阱的花費');
tz_def('MANUAL_TRAPPER_FREE', '部隊無法用掠奪解救。當部隊因成功的普通攻擊獲釋時，三分之一的陷阱會自動修復。若陷阱的擁有者釋放俘虜，所有陷阱都能修復。');
tz_def('MANUAL_TRAPPER_GAULS', '請注意，只有高盧能建造這座建築。');
tz_def('MANUAL_DESC_WOODCUTTER', '伐木場砍伐樹木以生產木材。伐木場的等級越高，產出的木材就越多。<br /><br />建造鋸木廠可以進一步提高產量。');
tz_def('MANUAL_DESC_CLAYPIT', '黏土從黏土坑採集。黏土坑的等級越高，產出的黏土就越多。');
tz_def('MANUAL_DESC_IRONMINE', '礦工在這裡開採珍貴的鐵礦。提升礦場等級就能提高鐵礦產量。建造鑄鐵廠可以進一步提高產量。<br /><br />');
tz_def('MANUAL_DESC_CROPLAND', '這裡生產你人口所需的糧食。提升農田等級就能提高糧食產量。<br /><br />建造磨坊和麵包房可以進一步提高產量。');
tz_def('MANUAL_DESC_SAWMILL', '伐木場砍下的木材在這裡加工。依等級而定，鋸木廠最多可將你的木材產量提高 25%。');
tz_def('MANUAL_DESC_BRICKYARD', '磚窯把黏土製成磚塊。依等級而定，磚窯最多可將你的黏土產量提高 25%。');
tz_def('MANUAL_DESC_IRONFOUNDRY', '鑄鐵廠熔煉鐵礦。依等級而定，鑄鐵廠最多可將你的鐵礦產量提高 25%。');
tz_def('MANUAL_DESC_GRAINMILL', '磨坊把穀物磨成麵粉。依等級而定，磨坊最多可將你的糧食產量提高 25%。');
tz_def('MANUAL_DESC_BAKERY', '麵包房把麵粉做成麵包。與磨坊併用時，糧食產量總共最多可提高 50%。');
tz_def('MANUAL_DESC_WAREHOUSE', '木材、黏土和鐵礦存放在倉庫。提升等級就能增加倉庫容量。');
tz_def('MANUAL_DESC_GRANARY', '農田產出的糧食存放在糧倉。提升等級就能增加糧倉容量。');
tz_def('MANUAL_DESC_BLACKSMITH', '戰士的武器在鐵匠鋪的熔爐中強化。提升等級後，你就能下令打造更好的武器。');
tz_def('MANUAL_DESC_ARMOURY', '戰士的盔甲在盔甲廠的熔爐中強化。提升等級後，你就能下令打造更好的盔甲。');
tz_def('MANUAL_DESC_MAINBUILDING', '村莊的建築大師住在主建築裡。等級越高，他們完成新建築的速度就越快。');
tz_def('MANUAL_DESC_RALLYPOINT', '你村莊的部隊在這裡集合。你可以從這裡派他們出去征服、掠奪或增援其他村莊。<br /><br />集結點只能建在主建築下方偏右的綠色草地上。');
tz_def('MANUAL_DESC_MARKETPLACE', '你可以在市場與其他玩家交易資源。等級越高，同時能運送的資源就越多。');
tz_def('MANUAL_DESC_EMBASSY', '大使館是外交官聚會的地方。等級 1 時你可以加入聯盟，擴建到等級 3 後，你甚至可以自己成立聯盟。<br /><br />聯盟的成員上限等於該聯盟內最高等級大使館的三倍。因此，等級 20 的大使館最多可讓 60 名玩家加入聯盟。');
tz_def('MANUAL_DESC_BARRACKS', '步兵可以在兵營訓練。等級越高，部隊訓練得越快。');
tz_def('MANUAL_DESC_STABLE', '騎兵可以在馬廄訓練。等級越高，部隊訓練得越快。');
tz_def('MANUAL_DESC_WORKSHOP', '投石機和衝車這類攻城武器可以在攻城武器廠建造。等級越高，單位生產得越快。');
tz_def('MANUAL_DESC_ACADEMY', '新的兵種可以在學院研發。提升等級後，你就能下令研究更強的單位。');
tz_def('MANUAL_DESC_CRANNY', '山洞用來在村莊遭受攻擊時藏起至少一部分資源。這些資源不會被偷走。<br /><br />等級 1 的山洞可容納每種資源 100 單位。高盧的山洞容量是其他種族的兩倍。<br /><br />提示<br />在 T3，山洞對條頓的效果為 66%。<br />在 T3.5，山洞對條頓的效果為 80%。');
tz_def('MANUAL_DESC_TOWNHALL', '你可以在市政廳舉行盛大的慶典。這樣的慶典會增加你的文化點。<br /><br />文化點是建立或征服新村莊所必需的。每座建築都會產生文化點，等級越高，產生得越多。藉由慶典，你可以在短時間內提高這項產量。');
tz_def('MANUAL_DESC_RESIDENCE', '行宮是一座小皇宮，國王或女王造訪村莊時會住在這裡。行宮能保護村莊，抵禦想要征服它的敵人。');
tz_def('MANUAL_DESC_PALACE', '帝國的國王或女王住在皇宮。你的領地同時只能有一座皇宮。你需要皇宮，才能把一座村莊宣告為首都。<br /><br />首都無法被征服。此外，只有首都能把資源田擴建到超過等級 10，也只有首都能建造石匠鋪。');
tz_def('MANUAL_DESC_TREASURY', '帝國的財富存放在寶物庫。一座寶物庫只能存放一件神器。<br /><br />小型神器需要等級 10 的寶物庫，大型神器則需要等級 20。');
tz_def('MANUAL_DESC_TRADEOFFICE', '交易所會改良商人的貨車，並配上強壯的馬匹。等級越高，你的商人能運載的數量就越多。');
tz_def('MANUAL_DESC_GREATBARRACKS', '大兵營讓你能同時建造更多單位，但花費是原本的三倍。<br /><br />它無法建在首都。');
tz_def('MANUAL_DESC_GREATSTABLE', '大馬廄讓你能同時建造更多單位，但花費是原本的三倍。<br /><br />它無法建在首都。');
tz_def('MANUAL_DESC_STONEMASON', '石匠鋪精通切石。建築擴建得越高，村莊建築的穩固度就越高。<br /><br />它只能建在首都。');
tz_def('MANUAL_DESC_BREWERY', '釀酒廠會釀出美味的蜜酒，士兵會在慶典時痛飲。<br /><br />這些酒讓你的士兵在戰鬥中更勇敢、更強壯（每等級 1%）。可惜司令官的說服力會降低，投石機也只能隨機命中。<br /><br />只有條頓能建造，且只能建在他們的首都。效果影響整個帝國。');
tz_def('MANUAL_DESC_HEROSMANSION', '在英雄園可以訓練英雄。你需要一名普通士兵成為英雄，因此要先有兵營或馬廄。<br /><br />建築到達 10、15、20 級時，英雄可以分別攻佔 1、2、3 座無人綠洲。依綠洲種類，某一種資源的產量會提高；有些綠洲會同時提高兩種。');
tz_def('MANUAL_DESC_GREATWAREHOUSE', '木材、黏土和鐵礦存放在倉庫。大倉庫空間更大，也比普通倉庫更乾燥、更安全。<br /><br />只能建在舊納塔村莊，或持有特殊納塔神器。');
tz_def('MANUAL_DESC_GREATGRANARY', '農田產出的糧食存放在糧倉。大糧倉空間更大，也比普通糧倉更乾燥、更安全。<br /><br />只能建在舊納塔村莊，或持有特殊納塔神器。');
tz_def('MANUAL_DESC_WONDER', '世界奇蹟是創造的驕傲。只有最強大、最富有的人，才蓋得起這樣的傑作，並守住它不被敵人覬覦。<br /><br />世界奇蹟只能建在舊納塔村莊，而且需要建築圖紙。從 50 級起還要第二張圖紙，這張必須由同一聯盟的另一名玩家持有。');
tz_def('MANUAL_DESC_HORSEDRINKING', '飲馬槽照料馬匹，因此也能加快訓練。<br /><br />飲馬槽會讓下列兵種的糧耗各減 1：10 級起為使節騎士，15 級起為帝國騎士，20 級起為將軍騎士。<br /><br />只有羅馬人可以建造飲馬槽。');
tz_def('MANUAL_DESC_GREATWORKSHOP', '大攻城武器廠可以生產投石機、衝車這類攻城兵器，但費用是普通單位的三倍。等級愈高，生產愈快。<br /><br />不能建在首都。');
tz_def('MANUAL_ATTACK_VALUE', '攻擊力');
tz_def('MANUAL_DEF_INFANTRY', '對步兵防禦');
tz_def('MANUAL_DEF_CAVALRY', '對騎兵防禦');
tz_def('MANUAL_VELOCITY', '速度');
tz_def('MANUAL_FIELDS_HOUR', '格/小時');
tz_def('MANUAL_CAN_CARRY', '可攜帶');
tz_def('MANUAL_TRAINING_DURATION', '訓練時間');
tz_def('MANUAL_NPC_NATARS', '說明僅供參考。納塔完全由系統控制，玩家無法扮演。');
tz_def('MANUAL_NPC_NATURE', '說明僅供參考。自然完全由系統控制，玩家無法扮演。');
tz_def('MANUAL_UDESC_ANIMAL_EXP', '英雄擊殺動物獲得的經驗，取決於該動物的糧耗。因此一隻 %s 只會給予 %d 點經驗。');
tz_def('MANUAL_UDESC_1', '古羅馬步兵是羅馬的通用步兵。攻防都算均衡，但不會強過專門兵種。');
tz_def('MANUAL_UDESC_2', '禁衛兵是皇帝的親衛，受訓專精防禦，攻擊很弱。');
tz_def('MANUAL_UDESC_3', '帝國兵是羅馬的頂尖攻擊步兵，快速又兇悍，是守軍的噩夢。訓練昂貴，也很花時間。');
tz_def('MANUAL_UDESC_4', '使節騎士是羅馬的偵察騎兵，速度很快，能探查敵村的資源與部隊。<br /><br />若被偵察的村莊沒有探子、使節騎士或尋路者，偵察就不會被發現。');
tz_def('MANUAL_UDESC_5', '帝國騎士是羅馬的標準騎兵，裝備精良。速度不是最快，但足以震懾沒有準備的敵人。養馬和養騎手都不便宜。');
tz_def('MANUAL_UDESC_6', '將軍騎士是羅馬的重騎兵，護甲厚、傷害高，但因此速度慢、攜帶少，糧耗也高。');
tz_def('MANUAL_UDESC_7', '攻城錘是步兵與騎兵的重型支援兵器，用來摧毀敵方城牆，提高攻破防禦的機會。');
tz_def('MANUAL_UDESC_8', '火焰投石機是優秀的遠程兵器，用來摧毀敵村的田地與建築。沒有護衛時幾乎無法自衛，記得派部隊同行。<br /><br />集結點等級愈高，投石愈準，也能指定更多建築。集結點 10 級時，除了山洞、石匠鋪和陷阱機以外的建築都能指定。<br />提示：火焰投石機在隨機瞄準時，仍可能打中山洞、陷阱機或石匠鋪。');
tz_def('MANUAL_UDESC_9', '參議員是種族選出的領袖，口才好，能說服村莊為帝國而戰。<br /><br />他每次向村民演說，敵方忠誠度就會下降，直到村莊歸你所有。');
tz_def('MANUAL_UDESC_10', '拓荒者經過長期訓練後離開村莊，為你建立新村莊。<br /><br />路程與建村都很艱辛，因此三人必須同行。每種資源需要 750 單位作為基礎。');
tz_def('MANUAL_UDESC_11', '棍棒兵是 Travian 最便宜的兵種。訓練快，攻擊中等，但護甲差。面對騎兵幾乎沒有還手之力。');
tz_def('MANUAL_UDESC_12', '在條頓軍隊裡，矛兵負責防禦。武器夠長，特別克制騎兵。<br /><br />不要拿他去進攻，攻擊能力很低。');
tz_def('MANUAL_UDESC_13', '這是條頓最強的步兵。攻防都強，但比其他兵種慢，也更貴。');
tz_def('MANUAL_UDESC_14', '探子走在條頓部隊前方，探查敵人的實力與村莊。他步行，所以比羅馬和高盧的偵察兵慢。他能看到敵方部隊、資源與防禦工事。<br /><br />若被偵察的村莊沒有探子、尋路者或使節騎士，偵察就不會被發現。');
tz_def('MANUAL_UDESC_15', '遊騎兵穿著重甲，是優秀的防禦單位。步兵很難突破他的盾。<br /><br />攻擊能力偏低，速度在騎兵裡也偏慢。訓練很久，費用也高。');
tz_def('MANUAL_UDESC_16', '條頓騎士令敵人恐懼。防禦時特別克制敵方騎兵。訓練與糧耗都極高。');
tz_def('MANUAL_UDESC_17', '衝車是步兵與騎兵的重型支援兵器，用來摧毀敵方城牆，提高攻破防禦的機會。');
tz_def('MANUAL_UDESC_18', '簡易投石機是優秀的遠程兵器，用來摧毀敵村的田地與建築。沒有護衛時幾乎無法自衛，記得派部隊同行。<br /><br />集結點等級愈高，投石愈準，也能指定更多建築。集結點 10 級時，除了山洞、石匠鋪和陷阱機以外的建築都能指定。<br />提示：簡易投石機在隨機瞄準時，仍可能打中山洞、陷阱機或石匠鋪。');
tz_def('MANUAL_UDESC_19', '條頓人從族人中選出司令官。光有勇武和謀略不夠，還得能說服外村居民加入自己的部族。<br /><br />他向村民演說愈多次，村莊忠誠度就降得愈多，直到村莊加入他的部族。');
tz_def('MANUAL_UDESC_21', '方陣兵是步兵，便宜又訓練得快。<br /><br />攻擊不高，但防禦時對步兵和騎兵都相當強。');
tz_def('MANUAL_UDESC_22', '劍客比方陣兵貴，但是攻擊單位。<br /><br />防禦偏弱，尤其怕騎兵。');
tz_def('MANUAL_UDESC_23', '尋路者是高盧的偵察兵。速度很快，能悄悄靠近敵方部隊、資源或建築打探情報。<br /><br />若被偵察的村莊沒有探子、使節騎士或尋路者，偵察就不會被發現。');
tz_def('MANUAL_UDESC_24', '雷法師是又快又強的騎兵，能攜帶大量資源，也很適合掠奪。<br /><br />防禦能力最多只算普通。');
tz_def('MANUAL_UDESC_25', '這支中型騎兵非常擅長防禦，主要用來對抗敵方步兵。造價與糧耗都偏高。');
tz_def('MANUAL_UDESC_26', '海頓騎士是高盧攻擊與對抗騎兵的王牌，這兩方面很少有人比得上。<br /><br />訓練與裝備非常昂貴。每小時消耗 3 單位糧食，出兵前要仔細想想值不值得。');
tz_def('MANUAL_UDESC_28', '投石機是優秀的遠程兵器，用來摧毀敵村的田地與建築。沒有護衛時幾乎無法自衛，記得派部隊同行。<br /><br />集結點等級愈高，投石愈準，也能指定更多建築。集結點 10 級時，除了山洞、石匠鋪和陷阱機以外的建築都能指定。<br />提示：投石機在隨機瞄準時，仍可能打中山洞、陷阱機或石匠鋪。');
tz_def('MANUAL_UDESC_29', '每個種族都有一位經驗老到的戰士，他的氣勢與演說能說服敵村居民加入自己的部族。<br /><br />族長在敵村城牆前演說愈多次，村莊忠誠度就降得愈多，直到村莊加入他的部族。');
tz_def('MANUAL_UDESC_31', '老鼠便宜，繁殖很快，但幾乎帶不了東西。<br /><br />這大概是自然單位裡最便宜、也最醜的一種。');
tz_def('MANUAL_UDESC_44', '納塔用鳥群收集敵情。從空中偵察很難攔下，但連一般村民也能聽見叫聲、看見成群的羽毛。');
tz_def('MANUAL_UDESC_41', '又長又尖的長槍是防線的主力。納塔長槍兵大膽靈巧，能迅速擊落敵方騎兵並了結他們。');
tz_def('MANUAL_UDESC_42', '頭盔、護腕和肩甲上的尖刺，讓他們得名荊棘戰士。這些為納塔而戰的人堅韌而訓練有素，貿然進攻只會換來一場血戰。');
tz_def('MANUAL_UDESC_43', '禁衛兵不騎馬，卻因全能而成為納塔軍隊裡最有價值的士兵之一。族人愛戴他們，敵人畏懼他們。訓練精良，敵人幾乎沒有勝算；厚重護甲也讓他們能當可靠的防禦部隊。');
tz_def('MANUAL_UDESC_45', '斧頭騎兵上馬出征時，只聞死亡與腐朽。他揮刃如農夫收割，往往一擊就能取下敵人首級。');
tz_def('MANUAL_UDESC_46', '只有最精銳的納塔戰士才能成為納塔騎士。刀盾與人幾乎合而為一，坐騎也是特育，普通馬匹扛不住那種重甲。他們的威名遠播，所到之處盡是恐懼。');
tz_def('MANUAL_UDESC_47', '只有納塔懂得駕馭這些巨獸。城牆和木柵欄都擋不住戰象。牠是行走的殺戮機器，擋路的一切都會被踏平。');
tz_def('MANUAL_UDESC_48', '納塔的工程技術遠超其他種族。射石機像一具巨大的弩，射出的彈丸沒有城牆或盾牌擋得住。拆開運往下一處戰場時，命中之處通常只剩廢墟。');
tz_def('MANUAL_UDESC_49', '納塔帝王向村民演說時，人們又懼又敬。他清楚自己的氣勢，一場激昂演說就能讓整座村莊臣服。');
tz_def('MANUAL_UDESC_50', '他們是敢於行動的工匠與建築大師，熟悉開墾、興建皇宮與鞏固村莊。納塔拓荒者三人一組出發，以納塔領主之名開闢土地。');
