tz_def('MANUAL_NF_D_11', '若村莊佔領了綠洲，個人資料會在對應村莊前顯示綠洲的資源類型與產量加成。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_12', '若有人邀請你加入聯盟，你會收到一則遊戲內訊息。');
tz_def('MANUAL_NF_D_13', '<h2>簡介</h2><br> 大使館與聯盟的舊規則有點像漏洞。大使館有固定的「容量」：依等級只能容納 3、6、9、12……最多 60 名成員。<br><br> 問題是，大使館升到 20 級、聯盟滿 60 人之後，你可以把建築整個拆掉，什麼事都不會發生。你只是不能再換聯盟，容量限制等於失效。若容量真的生效，滿員 60 人時連降到 19 級都不該被允許，因為 19 級裝不下這麼多人。<br><br> 因此這裡把大使館變成棋盤上更要緊的一顆棋。<br><br> <h2>新規則</h2><br> 拆除，以及在戰鬥中摧毀大使館，現在有一套新規則。看起來有點複雜，其實就是把聯盟的「容量」貫徹到底。<br><br> 重點是：大使館降得太低會受罰。聯盟成員的大使館不能低於 1 級。若低於 1 級，會先收到警告，接著被移出聯盟。<br><br> 聯盟創始人更嚴格，因為聯盟能否維持取決於他們。大使館不能拆到無法容納現有成員數的等級以下。<br><br> 若其他玩家或聯盟攻擊創始人放大使館的那座村莊，並用投石機和衝車打大使館，就可能出大問題。若創始人的其他村莊沒有等級足夠容納全體成員的大使館，聯盟可能解散。唯一例外是：若有其他成員的大使館等級足夠，該成員會自動成為領袖，聯盟因此保住。找不到這樣的玩家時，聯盟會完全解散。<br><br> <h2>詳細說明</h2><br> 想看圖解與更完整的說明，請看這份 <a href="https://docs.google.com/presentation/d/1KN1qVAlxVj7aAN6F9QkRai1oliajfxKPIaJ4MSodUac/edit#slide=id.p" target="_blank">Google 簡報</a>。');
tz_def('MANUAL_NF_D_14', '只要你在論壇串裡留過至少一則訊息，之後同一串有人留言，你就會收到遊戲內訊息（等於已訂閱該串）。');
tz_def('MANUAL_NF_D_15', '有了這項功能，你可以在個人資料說明裡加上自己種族的圖片與簡短說明（羅馬、條頓、高盧）。');
tz_def('MANUAL_NF_D_16', '對一般玩家沒有用處，這是給管理員與多獵手的。他們可以在個人資料說明裡加上各種圖片與說明。');
tz_def('MANUAL_NF_D_17', '若某座村莊有神器，個人資料會在該村莊前顯示。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_18', '若村莊是世界奇蹟的建造點，個人資料會在對應村莊旁顯示。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_19', '度假模式可在你長期離開時，保護帝國不受其他玩家的敵對行動影響。代價是發展會落後。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_20', '若你派出投石機進行普通攻擊，可以在集結點看到這次攻擊指定的目標。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_21', '手冊裡可以查到自然與納塔的兵力說明。');
tz_def('MANUAL_NF_D_22', '直接連結的位置會改變。原始 Travian T3.6 把直接連結放在右側選單、村莊列表下方，不太好用。啟用後會改到左側選單，方便許多。');
tz_def('MANUAL_NF_D_23', '頒給使用同一電子郵件遊玩達 3 年以上玩家的勳章，可加到個人資料說明。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_24', '頒給使用同一電子郵件遊玩達 5 年以上玩家的勳章，可加到個人資料說明。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_25', '頒給使用同一電子郵件遊玩達 10 年以上玩家的勳章，可加到個人資料說明。此功能源自 Travian T4。');
tz_def('MANUAL_NF_D_26', '頒給使用同一電子郵件遊玩達 10 年以上玩家的勳章，可加到個人資料說明。此功能源自 Travian T4。');
