tz_def('ANL_GAUL_DESC_2', '這個種族很好守，也能打侵略戰。你可以往任何方向發展（防守或進攻、獨行或支援、經商或掠奪、步兵或騎兵、拓荒或征服），但需要一點經驗與判斷。');
