tz_def('PUBLIC_RULES_EMAIL_OWNER', '註冊帳號所用的電子郵件地址，必須由註冊者本人專屬掌控。無論其他個人或聯盟約定如何，使用該電子郵件地址註冊帳號的人即視為帳號擁有者。帳號擁有者須對該帳號的一切行為負全部責任。');
