tz_def('PUBLIC_RULES_PASSWORD_OTHER_WORLD', '不過，可以把帳號密碼交給在不同遊戲世界遊玩的人，或完全沒有在玩的人，以便一起遊玩同一個帳號。');
tz_def('PUBLIC_RULES_PASSWORD_DAMAGE', '若有人因得知密碼而造成損害，不予補償。收到密碼的人同樣必須遵守 Travian 規則以及一般條款與條件。');
