tz_def('PUBLIC_RULES_SITTERS', '每位玩家有權指定兩名代理人，在擁有者離開時代為操作帳號。代理人必須完全為所代理帳號的利益來遊玩。濫用此功能將受處罰。');
tz_def('PUBLIC_RULES_SITTER_LOGIN', '帳號的代理人必須使用遊戲內的代理功能來操作。代理人不得用所代理帳號的密碼登入（見 &sect;1.2）。');
tz_def('PUBLIC_RULES_SITTER_DAMAGE', '代理人造成的損害不予補償。帳號擁有者必須對其任何代理人的行為負全部責任。若代理人未遵守這些規則以及 Travian 的一般條款與條件，帳號擁有者與代理人都可能受罰。');
tz_def('PUBLIC_RULES_SHARED_COMPUTER', '使用同一台電腦、並且想進入彼此帳號的玩家，必須使用代理功能。');
