tz_def('PUBLIC_RULES_BUGS', '不得利用程式錯誤謀取利益。濫用可能導致帳號受罰。');
tz_def('PUBLIC_RULES_REAL_MONEY', '任何以真實金錢買賣帳號、單位、村莊、資源、服務或 Travian 其他內容的行為都不允許。出售 Travian 帳號，以及透過拍賣網站或其他金錢往來進行的任何間接轉移（包含贈與），都不允許。');
tz_def('PUBLIC_RULES_POLITE_COMMUNICATION', '每個人都必須以有禮的口吻交談。多獵手可以不經警告修改不適當的個人資料與村莊名稱。');
tz_def('PUBLIC_RULES_BEHAVIOUR_INTRO', '以下行為將受處罰，適用於所有說明文字、帳號名稱、聯盟名稱、村莊名稱與訊息：');
