tz_def('ANL_FOUND_VILLAGE_Q', '如何開闢新村莊？');
tz_def('ANL_FOUND_VILLAGE_A', '要開闢新村莊，你需要 3 名拓荒者、地圖上的一塊空地，以及足夠的文化點。你不必先研究拓荒者，可以直接在 10、15 或 20 級皇宮，或 10、20 級行宮訓練他們。建造皇宮需要 5 級主建築與大使館。建造行宮只需要 5 級主建築。訓練好 3 名拓荒者後，在地圖上選一塊空地，點選「開闢新村莊」（提示：每種資源都需要 750 單位！），拓荒者就會離開原本的村莊，為你建立新村莊。');
tz_def('ANL_CONQUER_VILLAGE_Q', '如何征服村莊？');
tz_def('ANL_CONQUER_VILLAGE_A1', '這同樣至少需要 10 級行宮或皇宮，以及一座可以征服的敵方村莊。另外也需要足夠的文化點，和開闢新村莊一樣。你不能征服玩家的最後一座村莊，也不能征服其首都。');
tz_def('ANL_CONQUER_VILLAGE_A2', '一旦在學院研究出城鎮管理者（參議員、司令官或族長），就可以像拓荒者一樣在行宮或皇宮訓練他。不過，若已經訓練了拓荒者，就不能再訓練管理者。要征服村莊，必須先摧毀敵方的行宮或皇宮，再讓管理者多次攻擊目標村莊。當村莊忠誠度降到零，村莊就會歸你所有。之後你應該建造皇宮或行宮，把忠誠度重新提高。');
tz_def('ANL_CULTURE_POINTS_A', '建造與升級建築可以獲得文化點（CP）。已經產生的文化點可以在行宮與皇宮查看，那裡也會顯示額外村莊所需的文化點。');
tz_def('PUBLIC_RULES_PROGRAM_ERRORS_HEADING', '&sect;4 程式錯誤');
tz_def('PUBLIC_RULES_PUNISHMENT', '若違反這些遊戲規則，多獵手以及必要時的管理員會封鎖相關帳號，並決定適當處罰。處罰一律會超過違規所得到的利益。');
tz_def('PUBLIC_RULES_NO_REPLACEMENT', '停權期間損失的資源、建築、村莊或部隊不算作處罰，Travian 團隊也不會補發。任何玩家都無權因停權而要求退還或補償損失的 Plus／金幣時間。');
tz_def('PUBLIC_RULES_NO_SPECIAL_TREATMENT', 'Travian Plus／金幣使用者在遊戲規則上沒有特殊待遇，處理案件所需的時間與處罰都沒有例外。');
tz_def('PUBLIC_RULES_APPEALS', '玩家可以透過遊戲內訊息或電子郵件，聯絡封鎖自己的多獵手或管理員。封鎖、處罰或刪除不得在公開場合討論（例如聊天室或論壇）。申訴必須以英文撰寫。');
