tz_def('ADM_HOW_LONG_ONE_CRON_PHP_INVOCATION_KEEPS_WORKI', '單次 cron.php 會持續工作多久。多數共享主機只允許每 5 分鐘排程一次，而 Automation 大約每分鐘就要執行一次 &mdash; 所以一次呼叫會連續跑好幾個週期。排程若是「*/5」，請填 300。只有主機允許每分鐘排程時，才設為 0。');
tz_def('ADM_ENABLE_DISABLE_IF_A_PLAYER_LEAVES_AT_LEAST_O', '啟用（停用）：如果玩家在論壇的某個主題至少留過一則訊息，同一主題出現新訊息時，他就會收到遊戲內訊息（技術上等於已「訂閱」）。');
tz_def('ADM_ENABLE_DISABLE_THE_SERVER_MILESTONES_WIDGET', '啟用（停用）「伺服器里程碑」小工具（第一位建立第 2 座村莊、人口達到 1000、取得神器、佔領世界奇蹟、取得世界奇蹟建築圖紙、建立聯盟，或從其他玩家手中佔領村莊的人），顯示在統計 &raquo; 一般的最上方。');
tz_def('ADM_CREATE_PROMO_VOUCHER_CODES_PLAYERS_REDEEM_FO', '建立促銷／兌換碼，讓玩家在 Plus 頁面兌換金幣。可設定固定金幣數量、選用的總使用次數上限、每位玩家是否只能兌換一次，以及選用的到期日。若要給抓蟲者一次性獎勵，請建立使用次數上限&nbsp;1 的兌換碼 &mdash; 或使用');
tz_def('ADM_DENSITY_OVERLAYS_ON_THE_WORLD_GRID_TO_HELP_W', '在世界網格上疊加密度，方便調整開局平衡：村莊聚集在哪、哪個種族佔優勢、不活躍玩家在哪（荒區／適合出生的位置），以及攻擊目前落在哪。北方（+y）朝上。');
tz_def('ADM_HEURISTIC_CORRELATION_OF_ACCOUNT_PAIRS_BY_SH', '依共用 IP、子網路、裝置／瀏覽器指紋（User-Agent）、重疊的登入時間，以及資源轉移流向，對帳號配對做啟發式關聯。這是一項');
tz_def('ADM_USE_IT_TO_PRIORITISE_WHICH_PAIRS_A_HUMAN_SHO', '&mdash; 用來排出哪些配對該由人工優先調查。不會自動封禁。');
