tz_def('ADM_RECEIVED_FROM_OTHER_PLAYERS_VERSUS_AN_AUTOMA', '（來自其他玩家）對照依該玩家每小時產量自動算出的上限（');
tz_def('ADM_OF_PRODUCTION_PER_WINDOW_WW_VILLAGES_AND_ART', '的產量／視窗）。世界奇蹟村莊與神器村莊會標為補給例外。可設定手動覆寫，豁免某位玩家（世界奇蹟／受信任）或給予自訂上限。不會自動封鎖 &mdash; 這是給真人管理員的可見度 &amp; 控制。');
